from collections import defaultdict

n = int(input())
a_list = [int(input()) for _ in range(n)]

d = defaultdict(lambda: 0)

for a in a_list:
  d[a] += 1

ans = 0
for i in range(n):
  for j in range(n):
    product = a_list[i] * a_list[j]
    if product in d:
      ans += d[product]
print(ans)
